const request={"handle": "jameshoffmann", "sort": "latest", "seenVideoIds": []};
if(Object.values(request).some(v=>typeof v==='string'&&v.includes('REPLACE')))throw new Error('Replace all placeholders.');
if(!/^[A-Za-z0-9_.@-]{1,100}$/.test(request.handle)||!Array.isArray(request.seenVideoIds))throw new Error('Check channel handle and supplied history.');
return [{json:request}];

const body=$input.first().json;
const request=$('Research input').first().json;
if(typeof body.code!=='number'||body.code!==0)throw new Error('API business error; inspect saved response before repeating retrieval.');
const outer=body.data;
if(!outer||!['AVAILABLE','PARTIAL'].includes(outer.resourceStatus))throw new Error('Resource unavailable or unknown.');
const s=outer.data;
if(!s||typeof s!=='object'||Array.isArray(s))throw new Error('Expected supplier object under data.data.');
if(s.success!==undefined&&s.success!==true)throw new Error('Supplier success not established.');
if(typeof s.status_code==='number'&&s.status_code!==0)throw new Error('Supplier reports an error.');
const cell=v=>{if(v==null)return '';if(typeof v==='object')v=JSON.stringify(v);return typeof v==='string'&&(/^[\t\r\n]/.test(v)||/^[=+\-@]/.test(v.trimStart()))?"'"+v:v;};
const sourceUrl=(v,hosts)=>{if(typeof v!=='string'||!/^https:\/\/[A-Za-z0-9.-]+(?::[0-9]+)?(?:[/?#][^\s]*)?$/.test(v))throw new Error('Missing HTTPS source URL.');const host=v.match(/^https:\/\/([^/:?#]+)/)[1].toLowerCase();if(!hosts.some(h=>host===h||host.endsWith('.'+h)))throw new Error('Source hostname mismatch.');return v;};
const common={resource_status:outer.resourceStatus,source_fetched_at:outer.fetchedAt??'',observed_at_utc:new Date().toISOString(),execution_id:String($execution.id),query_or_input:request.query??request.url??request.handle,continuation:s.continuationToken??s.cursor??'',billing_status:outer.usage?.billingStatus??'',charged_credits:outer.usage?.chargedCredits??''};
const finish=(rows,returned)=>rows.map(row=>({json:Object.fromEntries(Object.entries({...row,...common,returned_count:returned,exported_count:rows.length,missing_fields:Object.keys(row).filter(k=>row[k]==null).join(';')}).map(([k,v])=>[k,cell(v)]))}));
if(!Array.isArray(s.videos))throw new Error('Expected data.data.videos array.');
if(!Array.isArray(request.seenVideoIds)||request.seenVideoIds.some(x=>typeof x!=='string'))throw new Error('seenVideoIds must be an explicit array of string IDs.');
const history=new Set(request.seenVideoIds),seen=new Set(),rows=[];
const expected=request.handle.replace(/^@/,'').toLowerCase();
for(const p of s.videos){
 if(!p||typeof p.id!=='string'||!p.id)throw new Error('Missing video identity.');
 if(p.channel?.handle&&p.channel.handle.replace(/^@/,'').toLowerCase()!==expected)throw new Error('Returned channel handle mismatch.');
 if(seen.has(p.id)||history.has(p.id))continue;seen.add(p.id);
 rows.push({source_id:p.id,source_url:sourceUrl(p.url,['youtube.com','youtu.be']),source_context:request.handle,title:p.title,views:p.viewCountInt,publish_date:p.publishDate,published_time:p.publishedTime,published_time_text:p.publishedTimeText,new_to_supplied_history:true});
 if(rows.length===20)break;
}
return finish(rows,s.videos.length);
